with ins as (insert into public.artist_external_ids (artist_slug,scheme,value,url,confidence,evidence) select x.s,x.k,x.v,x.u,'medium','sourced research 2026-11-03' from json_to_recordset('[{"s":"jael","k":"bandcamp","v":"https://knownasjael.bandcamp.com","u":"https://knownasjael.bandcamp.com"},{"s":"long-distances","k":"bandcamp","v":"https://longdistances.bandcamp.com/","u":"https://longdistances.bandcamp.com/"},{"s":"rohan-rakhit","k":"ra","v":"https://ra.co/dj/rohanrakhit","u":"https://ra.co/dj/rohanrakhit"},{"s":"spiralynk","k":"bandcamp","v":"https://spiralynk.bandcamp.com","u":"https://spiralynk.bandcamp.com"},{"s":"ak-sports","k":"musicbrainz","v":"1f33306e-ddc2-4917-8e1e-68c2a5e349e9","u":"https://musicbrainz.org/artist/1f33306e-ddc2-4917-8e1e-68c2a5e349e9"},{"s":"ak-sports","k":"ra","v":"https://ra.co/dj/sports","u":"https://ra.co/dj/sports"},{"s":"ak-sports","k":"deezer","v":"88991832","u":"https://www.deezer.com/artist/88991832"}]'::json) as x(s text,k text,v text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,scheme) do nothing returning 1) select count(*) from ins;